final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: Provisions an AWS IoT Core device policy scoped to thing names using a Lambda-backed custom resource.

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DevicePolicy
    Description: Prefix for the IoT Core policy name.

Resources:
  IoTPolicyCustomResourceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTPolicyManagementPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                Resource: !Sub 'arn:aws:iot:${AWS::Region}:${AWS::AccountId}:policy/*'

  IoTPolicyCustomResourceFunction:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Role: !GetAtt IoTPolicyCustomResourceRole.Arn
      Runtime: nodejs22.x
      Timeout: 60
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand, DeletePolicyCommand } = require('@aws-sdk/client-iot');
          const https = require('https');
          const url = require('url');

          const iot = new IoTClient({});

          function sendResponse(event, context, responseStatus, responseData, physicalResourceId) {
            return new Promise((resolve, reject) => {
              const responseBody = JSON.stringify({
                Status: responseStatus,
                Reason: `See CloudWatch Log Stream: ${context.logStreamName}`,
                PhysicalResourceId: physicalResourceId || context.logStreamName,
                StackId: event.StackId,
                RequestId: event.RequestId,
                LogicalResourceId: event.LogicalResourceId,
                Data: responseData
              });

              const parsedUrl = url.parse(event.ResponseURL);
              const options = {
                hostname: parsedUrl.hostname,
                port: 443,
                path: parsedUrl.path,
                method: 'PUT',
                headers: {
                  'content-type': '',
                  'content-length': Buffer.byteLength(responseBody)
                }
              };

              const req = https.request(options, (res) => {
                res.on('data', () => {});
                res.on('end', () => resolve());
              });

              req.on('error', (err) => reject(err));
              req.write(responseBody);
              req.end();
            });
          }

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify(event));
            const requestType = event.RequestType;
            const region = process.env.AWS_REGION;
            const accountId = event.ResourceProperties.AccountId;
            const policyName = event.ResourceProperties.PolicyName;

            let physicalResourceId = event.PhysicalResourceId || policyName;

            try {
              if (requestType === 'Create') {
                const policyDocument = {
                  Version: '2012-10-17',
                  Statement: [
                    {
                      Effect: 'Allow',
                      Action: 'iot:Connect',
                      Resource: `arn:aws:iot:${region}:${accountId}:client/\${iot:Connection.Thing.ThingName}`
                    },
                    {
                      Effect: 'Allow',
                      Action: [
                        'iot:Publish',
                        'iot:Receive'
                      ],
                      Resource: [
                        `arn:aws:iot:${region}:${accountId}:topic/\${iot:Connection.Thing.ThingName}/*`,
                        `arn:aws:iot:${region}:${accountId}:topic/$aws/things/\${iot:Connection.Thing.ThingName}/*`
                      ]
                    },
                    {
                      Effect: 'Allow',
                      Action: 'iot:Subscribe',
                      Resource: [
                        `arn:aws:iot:${region}:${accountId}:topicfilter/\${iot:Connection.Thing.ThingName}/*`,
                        `arn:aws:iot:${region}:${accountId}:topicfilter/$aws/things/\${iot:Connection.Thing.ThingName}/*`
                      ]
                    }
                  ]
                };

                await iot.send(new CreatePolicyCommand({
                  policyName: policyName,
                  policyDocument: JSON.stringify(policyDocument)
                }));

                physicalResourceId = policyName;
                await sendResponse(event, context, 'SUCCESS', { PolicyName: policyName }, physicalResourceId);
              } else if (requestType === 'Update') {
                // Return current policy name without modifying
                await sendResponse(event, context, 'SUCCESS', { PolicyName: physicalResourceId }, physicalResourceId);
              } else if (requestType === 'Delete') {
                if (physicalResourceId) {
                  try {
                    await iot.send(new DeletePolicyCommand({ policyName: physicalResourceId }));
                  } catch (deleteErr) {
                    console.log('Error deleting policy:', deleteErr);
                  }
                }
                await sendResponse(event, context, 'SUCCESS', {}, physicalResourceId);
              }
            } catch (error) {
              console.error('Handler error:', error);
              await sendResponse(event, context, 'FAILED', { Error: error.message }, physicalResourceId);
            }
          };

  DeviceIoTPolicy:
    Type: AWS::CloudFormation::CustomResource
    Properties:
      ServiceToken: !GetAtt IoTPolicyCustomResourceFunction.Arn
      PolicyName: !Sub '${PolicyNamePrefix}-${AWS::StackName}'
      AccountId: !Ref AWS::AccountId

Outputs:
  PolicyName:
    Description: The name of the provisioned IoT Core device policy.
    Value: !GetAtt DeviceIoTPolicy.PolicyName

AWSTemplateFormatVersion: '2010-09-09'
Description: Amazon Verified Permissions policy store and Cedar access control policies for a bookstore application.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Bookstore application policy store with strict Cedar schema validation
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verifiedpermissions/policy-store-id
      Description: SSM Parameter containing the Amazon Verified Permissions Policy Store ID for the Bookstore application
      Type: String
      Value: !Ref BookstorePolicyStore

  AdminPermitViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book
          Statement: >-
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  BlockedAdminForbidViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid one specific named administrator from viewing books
          Statement: >-
            forbid (
              principal == Bookstore::User::"BlockedAdmin",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherPermitOwnBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit publishers to view only the books they own
          Statement: >-
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  NamedUserPermitNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit a specific named user to view a specific named book
          Statement: >-
            permit (
              principal == Bookstore::User::"SpecialUser",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"SpecialBook"
            );

  CustomerPermitPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit customers with 2 or more years of membership to view premium offers
          Statement: >-
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal has yearsAsMember && principal.yearsAsMember >= 2
            };

  CustomerForbidPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid customers with less than 2 years of membership from viewing premium offers
          Statement: >-
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              !(principal has yearsAsMember && principal.yearsAsMember >= 2)
            };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers actions when the caller region is not US
          Statement: >-
            forbid (
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            when {
              context.region != "US"
            };

Outputs:
  PolicyStoreId:
    Description: The ID of the Bookstore Amazon Verified Permissions Policy Store
    Value: !Ref BookstorePolicyStore

  PolicyStoreArn:
    Description: The ARN of the Bookstore Amazon Verified Permissions Policy Store
    Value: !GetAtt BookstorePolicyStore.Arn

  SSMParameterName:
    Description: The name of the SSM Parameter storing the Policy Store ID
    Value: !Ref PolicyStoreIdParameter

  SSMParameterArn:
    Description: The ARN of the SSM Parameter storing the Policy Store ID
    Value: !Sub arn:${AWS::Partition}:ssm:${AWS::Region}:${AWS::AccountId}:parameter${PolicyStoreIdParameter}

AWSTemplateFormatVersion: '2010-09-09'
Description: AWS Step Functions and AWS Lambda Calculator demo template.

Resources:
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  CalculatorLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: LambdaLoggingPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !GetAtt CalculatorLogGroup.Arn

  CalculatorLambdaFunction:
    Type: AWS::Lambda::Function
    DependsOn: CalculatorLogGroup
    Properties:
      FunctionName: Calculator
      Runtime: nodejs24.x
      Handler: index.handler
      Role: !GetAtt CalculatorLambdaRole.Arn
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!operands || !Array.isArray(operands) || operands.length === 0) {
              throw new Error("Invalid operands: Must be a non-empty array of numbers.");
            }
            let result;
            switch (operator) {
              case 'add':
                result = operands.reduce((acc, curr) => acc + curr, 0);
                break;
              case 'subtract':
                result = operands.slice(1).reduce((acc, curr) => acc - curr, operands[0]);
                break;
              case 'multiply':
                result = operands.reduce((acc, curr) => acc * curr, 1);
                break;
              case 'divide':
                result = operands.slice(1).reduce((acc, curr) => {
                  if (curr === 0) {
                    throw new Error("Division by zero error.");
                  }
                  return acc / curr;
                }, operands[0]);
                break;
              default:
                throw new Error(`Unsupported operator: ${operator}`);
            }
            return {
              operator,
              operands,
              result
            };
          };

  StateMachineExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: InvokeLambdaPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - lambda:InvokeFunction
                Resource: !GetAtt CalculatorLambdaFunction.Arn

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineExecutionRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator State Machine routing supported operations to Lambda and failing on invalid operators",
          "StartAt": "DetermineOperation",
          "States": {
            "DetermineOperation": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "ExecuteCalculation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "ExecuteCalculation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "ExecuteCalculation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "ExecuteCalculation"
                }
              ],
              "Default": "UnknownOperator"
            },
            "ExecuteCalculation": {
              "Type": "Task",
              "Resource": "${CalculatorLambdaFunction.Arn}",
              "End": true
            },
            "UnknownOperator": {
              "Type": "Fail",
              "Cause": "The provided operator is not supported. Supported operators are: add, subtract, multiply, divide.",
              "Error": "UnsupportedOperatorError"
            }
          }
        }

Outputs:
  StateMachineArn:
    Description: ARN of the Calculator State Machine
    Value: !Ref CalculatorStateMachine

  LambdaFunctionArn:
    Description: ARN of the Calculator Lambda Function
    Value: !GetAtt CalculatorLambdaFunction.Arn

  SampleInput:
    Description: Sample execution input payload for the State Machine
    Value: '{"operator": "add", "operands": [1, 2]}'

AWSTemplateFormatVersion: '2010-09-09'
Description: AWS AppSync GraphQL API named TodoAPIwithJs backed by DynamoDB with JavaScript resolvers.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      SSESpecification:
        SSEEnabled: true
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Scan
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true

  ApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: Default API Key for TodoAPIwithJs

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          completed: Boolean
          owner: String!
          createdAt: String
          updatedAt: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          title: String!
          description: String
          completed: Boolean
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
          owner: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  DynamoDBDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoDynamoDBDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodoTable

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: createTodoFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const id = util.autoId();
          const timestamp = util.time.nowISO8601();
          const item = {
            id,
            completed: false,
            createdAt: timestamp,
            updatedAt: timestamp,
            ...input,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: getTodoFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id } = ctx.args;
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id }),
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: updateTodoFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...rest } = ctx.args.input;
          rest.updatedAt = util.time.nowISO8601();
          const sets = [];
          const expNames = {};
          const expValues = {};

          for (const key of Object.keys(rest)) {
            if (rest[key] !== undefined) {
              sets.push(`#${key} = :${key}`);
              expNames[`#${key}`] = key;
              expValues[`:${key}`] = rest[key];
            }
          }

          let updateExpression = '';
          if (sets.length > 0) {
            updateExpression = `SET ${sets.join(', ')}`;
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: updateExpression,
              expressionNames: expNames,
              expressionValues: util.dynamodb.toMapValues(expValues),
            },
            condition: {
              expression: 'attribute_exists(id)',
            },
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: deleteTodoFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id } = ctx.args;
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id }),
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: listTodosFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return {
            items: result.items,
            nextToken: result.nextToken,
          };
        }

  TodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: todosByOwnerFunction
      DataSourceName: !GetAtt DynamoDBDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: {
                '#owner': 'owner',
              },
              expressionValues: util.dynamodb.toMapValues({
                ':owner': owner,
              }),
            },
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type);
          }
          return {
            items: result.items,
            nextToken: result.nextToken,
          };
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
