AWSTemplateFormatVersion: '2010-09-09'
Description: Serverless GraphQL To-Do API using AWS AppSync with JavaScript Resolvers and Amazon DynamoDB.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  AppSyncDynamoDBServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: API key for SimpleTodoAPI testing

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          completed: Boolean!
          owner: String!
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          title: String!
          description: String
          completed: Boolean
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
          owner: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoDynamoDBTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBServiceRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodoTable

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          const { limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          const { items = [], nextToken } = ctx.result;
          return {
            items,
            nextToken,
          };
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: {
                '#owner': 'owner',
              },
              expressionValues: util.dynamodb.toMapValues({
                ':owner': owner,
              }),
            },
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          const { items = [], nextToken } = ctx.result;
          return {
            items,
            nextToken,
          };
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const now = util.time.nowISO8601();
          const item = {
            id: util.autoId(),
            completed: false,
            createdAt: now,
            updatedAt: now,
            ...ctx.args.input,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...updates } = ctx.args.input;
          updates.updatedAt = util.time.nowISO8601();

          const sets = [];
          const expressionNames = {};
          const expressionValues = {};

          for (const [key, value] of Object.entries(updates)) {
            if (value !== undefined) {
              const nameKey = `#${key}`;
              const valKey = `:${key}`;
              sets.push(`${nameKey} = ${valKey}`);
              expressionNames[nameKey] = key;
              expressionValues[valKey] = value;
            }
          }

          let updateExpression = 'SET ' + sets.join(', ');

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: updateExpression,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: {
              expression: 'attribute_exists(id)',
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

Outputs:
  GraphQLApiUrl:
    Description: The endpoint URL for the SimpleTodoAPI GraphQL API
    Value: !GetAtt GraphQLApi.GraphQLUrl

  GraphQLApiId:
    Description: The ID of the SimpleTodoAPI GraphQL API
    Value: !GetAtt GraphQLApi.ApiId

  GraphQLApiKey:
    Description: The API key for testing SimpleTodoAPI
    Value: !GetAtt GraphQLApiKey.ApiKey

  DynamoDBTableName:
    Description: Name of the DynamoDB table backing the GraphQL API
    Value: !Ref TodoTable
